<script setup lang="ts">
/**
 * The notice that belongs to the application frame and stays until its cause ends (`design/components/banner.md`).
 *
 * Generated by `pnpm shells` from `packages/shells/src/members/banner.ts`, the member's
 * framework-neutral description. Never edit it by hand: change the description and
 * run `pnpm shells`.
 */
import { onBeforeUnmount, onMounted, useTemplateRef, watch } from 'vue'

import { Icon, agentMember, focusAfterRemoval, useListening } from '@polymorph/vue'
import styles from '@polymorph/recipes/structure/banner.module.css'
import Button from '../controls/Button.vue'

export type BannerTone = NonNullable<BannerProps['tone']>

export interface BannerProps {
  /**
   * The ✕'s accessible name, default `Dismiss`; localized hosts pass their own.
   */
  dismissLabel?: string
  tone?: 'info' | 'warning' | 'danger' | 'neutral'
}

defineOptions({ name: 'Banner', inheritAttrs: false })

const props = withDefaults(defineProps<BannerProps>(), { dismissLabel: 'Dismiss', tone: 'neutral' })
const emit = defineEmits<{ dismiss: [] }>()
defineSlots<{
  action?: (props: Record<string, never>) => unknown
  default: (props: Record<string, never>) => unknown
}>()
const listening = useListening()
const closeRegion = useTemplateRef<HTMLElement>('closeRegion')
const root = useTemplateRef<HTMLElement>('root')
let release1: (() => void) | undefined
const effect1 = () => {
  release1?.()
  const ran = focusAfterRemoval(root.value)
  release1 = () => {
    ran()
  }
}
onMounted(effect1)
watch(() => root.value, effect1, { flush: 'post' })
onBeforeUnmount(() => release1?.())
let release2: (() => void) | undefined
const effect2 = () => {
  release2?.()
  const ran = agentMember({
    member: 'Banner',
    element: () => root.value,
    state: () => ({ tone: props.tone, dismissible: listening.dismiss }),
    actions: {
      dismiss: () =>
        (() => {
          if (!listening.dismiss) throw new Error('This banner has no dismiss control.')
          emit('dismiss')
        })(),
    },
    withholds: () => closeRegion.value,
  })
  release2 = () => {
    ran()
  }
}
onMounted(effect2)
onBeforeUnmount(() => release2?.())
</script>

<template>
  <div
    ref="root"
    :class="styles.banner"
    :role="tone === 'danger' ? 'alert' : 'status'"
    :data-tone="tone"
    data-member="banner"
  >
    <!-- glyph -->
    <span v-if="tone !== 'neutral'" :class="styles.glyph">
      <Icon :name="tone === 'danger' ? 'error' : tone === 'warning' ? 'warning' : 'info'" />
    </span>
    <!-- content -->
    <div :class="styles.content">
      <!-- text -->
      <div :class="styles.text">
        <slot />
      </div>
      <!-- action -->
      <div v-if="$slots.action" :class="styles.action">
        <slot name="action" />
      </div>
    </div>
    <!-- close -->
    <div v-if="listening.dismiss" ref="closeRegion" :class="styles.close">
      <Button
        variant="ghost"
        tone="neutral"
        size="sm"
        :iconOnly="true"
        icon="close"
        :label="dismissLabel"
        @click="emit('dismiss')"
      />
    </div>
  </div>
</template>
